bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 30
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync,appendFileSync,mkdirSync} from 'node:fs';
import pg from 'pg';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch(),api=createTelegramBotApi({token:readPrivateToken(process.env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000});
let outcome=0;
const audit='/var/lib/videobot/media-work/sale-duplicate-cleanup-20261123.jsonl';
try{
 const rows=(await pool.query(`SELECT r.delivery_key,r.status,r.topic_id,r.paid_message_id,r.free_message_ids,r.sale_mode,l.paid_video_file_id,l.title,l.price_stars,l.seller_user_id,EXTRACT(EPOCH FROM (NOW()-r.updated_at)) AS age_seconds FROM videobot_post_receipts r JOIN videobot_listings l USING (listing_id) WHERE r.status='sent' ORDER BY r.updated_at ASC`)).rows;
 const paidKeys=new Set((await pool.query("SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL")).rows.map(x=>x.delivery_key));
 const protectedRows=rows.filter(x=>paidKeys.has(x.delivery_key));
 if(protectedRows.length!==1)throw Error('PROTECTED_COUNT');
 const protectedRow=protectedRows[0];
 const duplicates=rows.filter(x=>x.delivery_key!==protectedRow.delivery_key&&
 x.topic_id===protectedRow.topic_id&&x.seller_user_id===protectedRow.seller_user_id&&
 x.title===protectedRow.title&&x.price_stars===protectedRow.price_stars&&
 x.paid_video_file_id===protectedRow.paid_video_file_id&&!paidKeys.has(x.delivery_key));
 if(duplicates.length<1||duplicates.length>15)throw Error('DUPLICATE_COUNT');
 const invoicePaid=(await pool.query("SELECT COUNT(*)::int AS n FROM videobot_video_invoice_orders WHERE telegram_payment_charge_id IS NOT NULL")).rows[0].n;
 if(invoicePaid!==0||duplicates.some(x=>Number(x.age_seconds)>46*3600))throw Error('PURCHASE_OR_AGE');
 const protectedIds=[protectedRow.paid_message_id,...(protectedRow.free_message_ids??[])].map(Number);
 const candidates=duplicates.flatMap(x=>[x.paid_message_id,...(x.free_message_ids??[])].map(Number));
 if(protectedIds.length!==3||new Set(protectedIds).size!==3||candidates.length!==duplicates.length*3||
 new Set(candidates).size!==candidates.length||candidates.some(n=>!Number.isSafeInteger(n)||n<=0||protectedIds.includes(n)))throw Error('MESSAGE_COLLISION');
 if(Number(process.env.VIDEOBOT_VIDEO_SALE_THREAD_ID)!==Number(protectedRow.topic_id))throw Error('TARGET_TOPIC_CHANGED');
 const chatId=-1002373696859;
 const me=await api('getMe',{}),chat=await api('getChat',{chat_id:chatId});
 if(me?.is_bot!==true||me.username?.toLowerCase()!=='createvdobot'||chat?.id!==chatId||chat.is_forum!==true)throw Error('TARGET_BOT_CHANGED');
 const own=await api('getChatMember',{chat_id:chatId,user_id:me.id});
 if(!['creator','administrator'].includes(own?.status)||own.status==='administrator'&&own.can_delete_messages!==true)throw Error('DELETE_RIGHTS');
 const purchased=(await pool.query("SELECT COUNT(*)::int AS n FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key=$1",[protectedRow.delivery_key])).rows[0].n;
 if(purchased<1)throw Error('PURCHASE_GUARD');
 const dir='/var/lib/videobot/media-work';
 mkdirSync(dir,{recursive:true});
 let deleted=0;
 for(const entry of duplicates){
  for(const id of [entry.paid_message_id,...entry.free_message_ids].map(Number)){
   if(protectedIds.includes(id))throw Error('PROTECTED_MESSAGE');
   // This is the existing sales Bot's own posted receipt, in the verified topic.
   const response=await api('deleteMessage',{chat_id:chatId,message_id:id});
   if(response!==true)throw Error('TELEGRAM_DELETE_NOT_ACKNOWLEDGED');
   appendFileSync(audit,JSON.stringify({at:new Date().toISOString(),delivery_key:entry.delivery_key,
    message_id:id,result:'telegram_delete_ack',protected_delivery_key:protectedRow.delivery_key})+'\n',{mode:0o600});
   deleted++;
  }
 }
 outcome=deleted===candidates.length?0:90;
}catch(err){
 const code=['PROTECTED_COUNT','DUPLICATE_COUNT','PURCHASE_OR_AGE','MESSAGE_COLLISION','TARGET_TOPIC_CHANGED','TARGET_BOT_CHANGED','DELETE_RIGHTS','PURCHASE_GUARD','PROTECTED_MESSAGE','TELEGRAM_DELETE_NOT_ACKNOWLEDGED','Telegram API request failed'];
 const i=code.findIndex(x=>String(err?.message??'').includes(x));
 outcome=i<0?89:60+i;
}finally{await net.close();await pool.end()}
process.exit(outcome);
NODE
